const ROOT=document.getElementById('app');
const cdn='https://cdn.jsdelivr.net/npm/lucide-static@0.468.0/icons/';
const I=(id,cl='')=>`<img class="icon ${cl}" src="${cdn}${id}.svg" alt="" aria-hidden="true" loading="lazy">`;
const H=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const N=x=>String(x??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const cap=x=>x?.length?x[0].toUpperCase()+x.slice(1):'';
let D={},X={},originalColors={};
const defaults=['#de5163','#f47b48','#8663bf','#ae76a9','#db9a30','#009f8e','#40a2ac','#a58a2e','#678b51','#686de0','#b966a8','#5479b5'];
const state={view:'cruce',mapView:'bands',group:'all',family:'all',query:'',onlyKnown:true,focused:'legend',drawer:null,activeDrug:'ceftriaxona',activeMicro:'p-aeruginosa',activeSyndrome:'nac',compare:['ceftriaxona','cefepima','piptazo'],density:'regular',sort:'known',paletteOpen:false,searchOpen:false,searchQuery:'',filtersOpen:false,libraryTab:'detail',learnId:'gram',palettePreset:'spectrum',hiddenUnknown:false};
const statusMap={active:{label:'Actividad habitual',symbol:'✓',short:'Actividad'},conditional:{label:'Depende del contexto',symbol:'≈',short:'Condicionada'},none:{label:'Sin actividad útil',symbol:'×',short:'No cubre'},unknown:{label:'Sin evaluar',symbol:'·',short:'Sin datos'}};
const activeQuery=()=>N(state.query);
function initialPalette(){
  const base={};(D.groups||[]).forEach((g,i)=>base[g.id]=defaults[i%defaults.length]);
  try{ const saved=JSON.parse(localStorage.getItem('atb_atlas_palette_v5')||'null'); if(saved&&typeof saved==='object')Object.assign(base,saved); }catch{}
  return base;
}
let colors={};
function applyPalette(){ Object.entries(colors).forEach(([key,val])=>document.documentElement.style.setProperty(`--g-${key}`,val)); }
const G=id=>D.groups.find(g=>g.id===id);
const A=id=>D.antibiotics.find(a=>a.id===id);
const P=id=>D.pathogens.find(p=>p.id===id);
const S=id=>D.syndromes.find(s=>s.id===id);
const R=(a,p)=>D.relations.find(r=>r.antibiotic===a&&r.pathogen===p);
const relByDrug=id=>D.relations.filter(r=>r.antibiotic===id);
const relByMicro=id=>D.relations.filter(r=>r.pathogen===id);
const microIn=id=>D.pathogens.filter(p=>p.groupId===id);
const minWords=(s,n=15)=>String(s||'').split(/\s+/).slice(0,n).join(' ')+(String(s||'').split(/\s+/).length>n?'…':'');
const sourceLink=id=>{ const ref=D.guides[id] || null;return ref?`<a class="source-link" href="${H(ref.url||'#')}" target="_blank" rel="noopener noreferrer">${H(ref.title||id)} ${I('arrow-up-right')}</a>`:'';};
const groupTone=id=>`style="--tone:${H(colors[id]||'#6b7280')}"`;
function nav(view){return `#/${view}`;}
function groupPill(groupId,small=false){const g=G(groupId);return g?`<span class="group-pill ${small?'sm':''}" ${groupTone(groupId)}><span class="pill-dot"></span>${H(g.name)}</span>`:'';}
function statusKey(status){return statusMap[status]?status:'unknown';}
function glyph(status){status=statusKey(status);return `<span class="status-symbol st-${status}" title="${H(statusMap[status].label)}">${statusMap[status].symbol}</span>`;}
function statusLabel(status){status=statusKey(status);return `<span class="status-caption st-${status}">${glyph(status)} ${statusMap[status].label}</span>`;}
function statCountDrug(a){return relByDrug(a.id).filter(r=>r.status!=='unknown').length;}
function scopeGroups(){ return state.group==='all'?D.groups:D.groups.filter(g=>g.id===state.group); }
function familyNames(){ return [...new Set(D.antibiotics.map(a=>a.family))].sort((a,b)=>a.localeCompare(b,'es')); }
function pageHeader(kicker,title,subtitle,trail=''){
  return `<div class="page-heading"><div class="heading-eyebrow"><span class="eyebrow-mark"></span>${H(kicker)}</div><div class="heading-head"><h1>${title}</h1><div class="heading-tools">${trail}</div></div><p>${H(subtitle)}</p></div>`;
}
function iconButton(icon,action,label,cls=''){return `<button class="icon-button ${cls}" data-action="${H(action)}" aria-label="${H(label)}" title="${H(label)}">${I(icon)}</button>`;}
function btn(label,action,cls='',icon=''){return `<button class="ui-button ${cls}" data-action="${H(action)}">${icon?I(icon):''}${H(label)}</button>`;}
function openIcon(icon,txt,action){return `<button class="side-link ${state.view===action?'selected':''}" data-action="nav:${action}">${I(icon)}<span>${txt}</span>${state.view===action?'<span class="nav-arrow">●</span>':''}</button>`;}
function shell(content){
 const route=state.view;
 ROOT.innerHTML=`<div class="app-frame">
 <aside class="shell-side">
   <div class="wordmark" data-action="nav:cruce"><div class="logo-icon"><span>A</span><i></i></div><div><strong>ATB <b>ATLAS</b></strong><small>MICROBIOLOGÍA VISUAL</small></div></div>
   <div class="side-overline">HERRAMIENTAS</div>
   <nav class="side-links" aria-label="Navegación">
   ${openIcon('layout-dashboard','Micro × Antibiótico','cruce')}
   ${openIcon('pill','Solo antibióticos','antibioticos')}
   ${openIcon('microscope','Solo microorganismos','microorganismos')}
   <div class="side-rule"></div>
   ${openIcon('git-branch','Clínica y síndromes','clinica')}
   ${openIcon('layers','Comparador','comparar')}
   ${openIcon('book-open-text','Aprender','aprender')}
   ${openIcon('library','Guías y fuentes','fuentes')}
   </nav>
   <div class="sidebar-bottom"><div class="side-status"><span class="online-dot"></span> BASE ABIERTA <b>2026</b></div><button class="side-palette" data-action="palette">${I('palette')} Colores del atlas ${I('arrow-right')}</button><div class="side-foot">EDICIÓN 05 <span>/</span> REWORK EDITORIAL</div></div>
 </aside>
 <div class="shell-main"><header class="top-header"><div class="top-current"><span>EXPLORADOR</span><b>/</b><strong>${H(({cruce:'MAPA DE ESPECTRO',antibioticos:'ANTIBIÓTICOS',microorganismos:'MICROORGANISMOS',clinica:'CLÍNICA',comparar:'COMPARAR',aprender:'APRENDER',fuentes:'FUENTES'})[route]||'ATLAS')}</strong></div>
 <div class="top-actions"><button class="global-search" data-action="search-open">${I('search')} <span>Buscar organismo, fármaco o infección</span><kbd>⌘ K</kbd></button>${iconButton('share-2','share','Copiar enlace')}${iconButton('palette','palette','Personalizar colores')}<div class="release-dot">V5</div></div></header>
 <main class="main-content">${content}</main><footer class="footer-line"><span><b>ATB ATLAS</b> · Recurso académico de comprensión y comparación</span><span>Actividad no equivale a prescripción · <a href="#/fuentes">Fuentes ↗</a></span></footer></div>
 ${state.drawer?renderDrawer():''}${state.paletteOpen?renderPalette():''}${state.searchOpen?renderSearch():''}</div>`;
 applyPalette();
}
function crossModeStrip(){return `<div class="mode-strip">
<button class="mode-tile ${state.view==='cruce'?'active':''}" data-action="nav:cruce"><span class="mode-icon coral">${I('table-2')}</span><span><b>Micro × ATB</b><small>Cruza ambas bibliotecas</small></span><em>01</em></button>
<button class="mode-tile ${state.view==='antibioticos'?'active':''}" data-action="nav:antibioticos"><span class="mode-icon lilac">${I('pill')}</span><span><b>Antibióticos</b><small>Familias, espectro y límites</small></span><em>02</em></button>
<button class="mode-tile ${state.view==='microorganismos'?'active':''}" data-action="nav:microorganismos"><span class="mode-icon mint">${I('microscope')}</span><span><b>Microorganismos</b><small>Identidad y clínica</small></span><em>03</em></button>
</div>`;}
function legend(){return `<div class="legend-list"><span>${glyph('active')} Actividad habitual</span><span>${glyph('conditional')} Condicionada</span><span>${glyph('none')} Sin actividad útil</span><span>${glyph('unknown')} Sin evaluar</span></div>`;}
function taxonomyRail(){return `<div class="filter-side"><div class="filter-title">TERRITORIOS <span>${D.groups.length}</span></div><button class="taxon-choice ${state.group==='all'?'on':''}" data-action="group:all"><span class="rainbow-mark"></span><b>Todos los grupos</b><small>${D.pathogens.length}</small></button>
 ${D.groups.map(g=>`<button class="taxon-choice ${state.group===g.id?'on':''}" data-action="group:${g.id}" ${groupTone(g.id)}><span class="taxon-dot"></span><b>${H(g.name)}</b><small>${microIn(g.id).length}</small></button>`).join('')}
 <div class="side-helper">${I('lightbulb')} <span>Selecciona un grupo para ampliar sus especies y reducir la matriz.</span></div></div>`;}
function crossControls(){return `<div class="toolbar">
 <div class="toolbar-main"><div class="seg-control"><button class="${state.mapView==='bands'?'active':''}" data-action="map:bands">${I('align-justify')} Bandas</button><button class="${state.mapView==='matrix'?'active':''}" data-action="map:matrix">${I('grid-3x3')} Matriz</button><button class="${state.mapView==='reverse'?'active':''}" data-action="map:reverse">${I('arrow-left-right')} Invertida</button></div>
 <div class="toolbar-right">${btn('Filtros','filter-toggle','ghost','sliders-horizontal')}${btn('Limpiar','reset-filter','ghost','rotate-ccw')}${iconButton('help-circle','legend','Cómo leer el mapa')}</div></div>
 ${state.filtersOpen?`<div class="filter-dropdown"><label><small>Familia farmacológica</small><select id="familySelect"><option value="all">Todas las familias</option>${familyNames().map(f=>`<option ${state.family===f?'selected':''} value="${H(f)}">${H(f)}</option>`).join('')}</select></label><label><small>Buscar fármaco / patógeno</small><input id="crossSearch" placeholder="cefepima, MRSA, BLEE…" value="${H(state.query)}"></label><label class="checkline"><input type="checkbox" id="knownToggle" ${state.onlyKnown?'checked':''}> Priorizar relaciones registradas</label><label><small>Densidad</small><select id="densitySelect"><option value="regular" ${state.density==='regular'?'selected':''}>Cómoda</option><option value="compact" ${state.density==='compact'?'selected':''}>Compacta</option></select></label></div>`:''}
 </div>`;}
function getActiveAntibiotics(){let list=D.antibiotics.filter(a=>(state.family==='all'||a.family===state.family));if(state.onlyKnown)list=list.filter(a=>statCountDrug(a)>0);let q=activeQuery();if(q){let drugs=list.filter(a=>N([a.name,a.family,a.subgroup,a.id].join(' ')).includes(q));if(drugs.length)list=drugs;else{let matchingMicro=D.pathogens.filter(p=>N([p.name,p.groupId,...(p.aliases||[])].join(' ')).includes(q));let ids=new Set(matchingMicro.flatMap(p=>relByMicro(p.id).map(r=>r.antibiotic)));if(ids.size)list=list.filter(a=>ids.has(a.id));else list=[];}}
 return list.sort((a,b)=>a.family.localeCompare(b.family,'es')||a.subgroup.localeCompare(b.subgroup,'es')||a.name.localeCompare(b.name,'es'));}
function summaryStatus(drugId,gid){let microbes=microIn(gid);let docs=microbes.map(p=>R(drugId,p.id)).filter(Boolean);const counts={active:0,conditional:0,none:0};docs.forEach(r=>{if(counts[r.status]!==undefined)counts[r.status]++;});return {counts,known:docs.length,total:microbes.length,unknown:microbes.length-docs.length};}
function bandItem(drug,g){let data=summaryStatus(drug.id,g.id);let total=data.total;let known=data.known;const micro=microIn(g.id);return `<button class="coverage-territory ${!known?'territory-unmapped':''}" ${groupTone(g.id)} data-action="group-inspect" data-drug="${H(drug.id)}" data-group="${H(g.id)}" aria-label="${H(drug.name+' por '+g.name)}">
   <div class="coverage-mini">${micro.map(p=>{let r=R(drug.id,p.id);return `<span class="micro-block ${r?'s-'+statusKey(r.status):'s-unknown'}" title="${H(p.name)}: ${r?statusMap[statusKey(r.status)].label:'Sin evaluar'}"></span>`;}).join('')}</div>
   <div class="coverage-caption"><b>${known?`${known}/${total}`:'—'}</b><small>${known?`${data.counts.active?'✓'+data.counts.active+' ':''}${data.counts.conditional?'≈'+data.counts.conditional+' ':''}${data.counts.none?'×'+data.counts.none:''}`:'Sin datos'}</small></div>
 </button>`;}
function renderBands(){const groups=scopeGroups();const list=getActiveAntibiotics();let lastFamily='';return `<div class="map-scroll" id="map-scroll"><table class="band-table ${state.density==='compact'?'compact':''}"><colgroup><col class="fixed-col">${groups.map(()=>'<col class="group-col">').join('')}</colgroup><thead><tr><th class="stick-col table-corner"><span>${I('pill')} ANTIBIÓTICOS</span><small>Familia y subgrupo</small></th>${groups.map(g=>`<th class="territory-head" ${groupTone(g.id)}><div class="territory-color"></div><b>${H(g.name)}</b><small>${microIn(g.id).length} microorganismos</small></th>`).join('')}</tr></thead><tbody>
 ${list.map(a=>{let header='';if(a.family!==lastFamily){lastFamily=a.family;header=`<tr class="family-tr"><th colspan="${groups.length+1}"><span class="family-divider"></span>${H(a.family.toUpperCase())}<small>${D.antibiotics.filter(z=>z.family===a.family).length} agentes</small></th></tr>`;}
 return `${header}<tr><th class="drug-sticky stick-col"><button data-action="drug:${H(a.id)}"><strong>${H(a.name)}</strong><small>${H(a.subgroup)}</small></button></th>${groups.map(g=>`<td>${bandItem(a,g)}</td>`).join('')}</tr>`;}).join('')}
 </tbody></table></div>${list.length?'':emptyResult('Ningún antibiótico coincide con el filtro actual.')}<div class="map-footer">${I('info')} <span>Cada bloque representa especies individuales dentro de un grupo. La cantidad indica <b>relaciones registradas</b>, no sensibilidad ni eficacia clínica.</span></div>`;}
function renderMatrix(reverse=false){const q=activeQuery();let drugs=getActiveAntibiotics().slice(0,60);let micro=D.pathogens.filter(p=>(state.group==='all'||p.groupId===state.group));if(q){let found=micro.filter(p=>N(p.name+' '+p.groupId+' '+(p.aliases||[]).join(' ')).includes(q));if(found.length)micro=found;}
 if(!reverse){const displayMicro=micro.slice(0,40);return `<div class="map-scroll"><table class="precision-matrix"><thead><tr><th class="stick-col table-corner">ANTIBIÓTICO ↓ <small>ESPECIE →</small></th>${displayMicro.map(p=>`<th class="micro-head" ${groupTone(p.groupId)}><div class="territory-color"></div><button data-action="micro:${H(p.id)}">${H(p.name)}</button></th>`).join('')}</tr></thead><tbody>${drugs.map(a=>`<tr><th class="stick-col drug-sticky"><button data-action="drug:${H(a.id)}"><strong>${H(a.name)}</strong><small>${H(a.subgroup)}</small></button></th>${displayMicro.map(p=>matrixCell(a,p)).join('')}</tr>`).join('')}</tbody></table></div><div class="map-footer">${I('info')} Matriz por especie · muestra hasta 40 microorganismos, filtra un territorio para mayor precisión.</div>`;}
 const displayMicro=micro.slice(0,65),displayDrugs=drugs.slice(0,35);return `<div class="map-scroll"><table class="precision-matrix"><thead><tr><th class="stick-col table-corner">MICROORGANISMO ↓ <small>FÁRMACO →</small></th>${displayDrugs.map(a=>`<th class="micro-head"><button data-action="drug:${H(a.id)}">${H(a.name)}</button></th>`).join('')}</tr></thead><tbody>${displayMicro.map(p=>`<tr><th class="stick-col drug-sticky" ${groupTone(p.groupId)}><button data-action="micro:${H(p.id)}"><strong>${H(p.name)}</strong><small>${H(G(p.groupId)?.name||'')}</small></button></th>${displayDrugs.map(a=>matrixCell(a,p)).join('')}</tr>`).join('')}</tbody></table></div><div class="map-footer">${I('info')} Vista invertida · organiza las especies en filas y los antibióticos en columnas.</div>`;
}
function matrixCell(a,p){const r=R(a.id,p.id),st=statusKey(r?.status);return `<td class="matrix-td"><button class="matrix-symbol s-${st}" ${groupTone(p.groupId)} data-action="relation" data-drug="${H(a.id)}" data-micro="${H(p.id)}" title="${H(a.name)} × ${H(p.name)} · ${statusMap[st].label}">${statusMap[st].symbol}</button></td>`;}
function renderCross(){const totalKnown=D.relations.length;const group=state.group==='all'?'Todos los grupos':G(state.group)?.name;return `${pageHeader('01 / EXPLORADOR BIDIRECCIONAL','Un mapa para <i>entender</i> el espectro.','Selecciona un territorio, descubre especies y compara antibióticos sin memorizar una tabla interminable.',btn('Comparar antibióticos','nav:comparar','subtle','arrow-up-right'))}
 ${crossModeStrip()}
 <div class="content-plate"><div class="section-kicker"><span class="section-accent"></span> CARTOGRAFÍA DE COBERTURA <span class="section-right">${D.antibiotics.length} ATB · ${D.pathogens.length} microorganismos · ${totalKnown} cruces documentados</span></div>
 <div class="learn-rule"><div class="rule-leading">${I('scan-eye')}<b>¿Cómo se lee?</b></div><div class="rule-middle"> <b>COLOR</b> = grupo de microorganismos <span class="rule-sep">/</span> <b>SÍMBOLO</b> = relación de espectro</div>${iconButton('chevron-down','legend','Abrir leyenda')}</div>
 ${state.focused==='legend'?`<div class="legend-expanded">${legend()}<p><strong>No se ha evaluado</strong> no significa resistencia. Una relación registrada tampoco sustituye el antibiograma.</p></div>`:''}
 <div class="spectrum-workbench"><div class="workbench-lead"><div><h2>Mapa de cobertura</h2><p>${H(group)} · Vista ${state.mapView==='bands'?'por bandas':state.mapView==='matrix'?'por especies':'invertida'}</p></div><span class="workbench-numbers">${getActiveAntibiotics().length} fármacos visibles</span></div>${crossControls()}<div class="workspace-grid">${taxonomyRail()}<div class="workspace-map">${state.mapView==='bands'?renderBands():renderMatrix(state.mapView==='reverse')}</div></div></div></div>
 <div class="after-map"><div class="mini-insight"><span class="insight-index">LECTURA 01</span><h3>Una cobertura tiene contexto.</h3><p>La matriz distingue lo registrado de lo desconocido. La decisión clínica depende de especie, fenotipo de resistencia, susceptibilidad, penetración, síndrome y paciente.</p>${btn('Aprender a interpretar','nav:aprender','ink','arrow-right')}</div><div class="insight-tiles"><div class="insight-tile"><span class="tile-orb coral">${I('microscope')}</span><b>¿No conoces el microorganismo?</b><small>Explora Gram, morfología, hábitat y enfermedades.</small>${btn('Explorar microorganismos','nav:microorganismos','link','arrow-right')}</div><div class="insight-tile"><span class="tile-orb lime">${I('pill')}</span><b>¿Tienes un antibiótico en mente?</b><small>Conoce grupo, subgrupo, mecanismo y límites.</small>${btn('Explorar antibióticos','nav:antibioticos','link','arrow-right')}</div></div></div>`;}
function emptyResult(message){return `<div class="empty-msg">${I('search-x')} ${H(message)}</div>`;}
function catalogHeader(kicker,title,desc,icon){return `<div class="catalog-heading"><div class="catalog-title-icon">${I(icon)}</div><div><span class="mono-overline">${H(kicker)}</span><h2>${H(title)}</h2><p>${H(desc)}</p></div></div>`;}
function filterTabs(type){const groups=type==='antibioticos'?familyNames():D.groups.map(g=>g.name);return groups;}
function drugList(){const fams=familyNames();return `<div class="catalog-filter"><div class="catalog-search">${I('search')}<input type="search" id="drugSearch" placeholder="Buscar fármaco, familia o subgrupo…" value="${H(state.query)}"/></div><div class="catalog-label">GRUPOS FARMACOLÓGICOS <span>${fams.length}</span></div><div class="catalog-groups"><button class="family-filter ${state.family==='all'?'active':''}" data-action="family:all">Todos los antibióticos <small>${D.antibiotics.length}</small></button>${fams.map(f=>`<button class="family-filter ${state.family===f?'active':''}" data-action="family:${H(f)}">${H(f)} <small>${D.antibiotics.filter(a=>a.family===f).length}</small></button>`).join('')}</div></div>`;}
function drugCards(){let list=D.antibiotics.filter(a=>(state.family==='all'||a.family===state.family)&&N([a.name,a.family,a.subgroup].join(' ')).includes(activeQuery()));let grouped={};list.forEach(a=>(grouped[a.family]??=[]).push(a));return `<div class="catalog-stream">${Object.entries(grouped).map(([family,drugs])=>`<div class="catalog-family-title"><span>${H(family)}</span><i>${drugs.length} agentes</i></div>${drugs.map(a=>`<button class="catalog-row ${state.activeDrug===a.id?'selected':''}" data-action="drug-select:${H(a.id)}"><span class="drug-mark">${I('pill')}</span><span class="catalog-row-copy"><b>${H(a.name)}</b><small>${H(a.subgroup)}</small></span><span class="row-trailing">${statCountDrug(a)?`${statCountDrug(a)} relaciones`:'Por revisar'} ${I('chevron-right')}</span></button>`).join('')}`).join('')||emptyResult('No se encontraron antibióticos.')}</div>`;}
function drugDetail(){const a=A(state.activeDrug)||D.antibiotics[0];const relations=relByDrug(a.id),mapped=relations.filter(r=>r.status!=='unknown');let byGroup=D.groups.map(g=>({g,rows:microIn(g.id).map(p=>({p,r:R(a.id,p.id)})).filter(x=>x.r)})).filter(x=>x.rows.length);return `<div class="detail-head"><div class="head-number">ATB / ${String(D.antibiotics.indexOf(a)+1).padStart(3,'0')}</div><h2>${H(a.name)}</h2><div class="detail-subhead"><span class="detail-tag orange">${H(a.family)}</span><span class="detail-tag purple">${H(a.subgroup)}</span>${a.newer?'<span class="detail-tag lime">AGENTE RECIENTE</span>':''}</div><p>${H(a.context||a.pearl||'Explorar espectro, mecanismo y limitaciones.')}</p></div>
 <div class="fact-ribbon"><div><small>FAMILIA</small><b>${H(a.family)}</b></div><div><small>SUBGRUPO</small><b>${H(a.subgroup)}</b></div><div><small>RELACIONES EN BASE</small><b>${mapped.length} <i>/ ${D.pathogens.length}</i></b></div><div><small>REVISIÓN</small><b class="flag-review">${a.review==='pendiente_revision_clinica'?'Pendiente':'Editorial'}</b></div></div>
 <section class="subsection"><div class="subsection-head"><span>01</span><h3>Mecanismo de acción</h3></div><div class="mechanism-visual"><div class="mechanism-symbol">${I('circuit-board')}</div><div><b>${H(a.mechanism||'Mecanismo por caracterizar')}</b><p>La actividad depende de que la diana esté presente y accesible, y de que el microorganismo no haya desarrollado mecanismos de resistencia relevantes.</p></div></div></section>
 <section class="subsection"><div class="subsection-head"><span>02</span><h3>Espectro documentado</h3><small>${mapped.length} cruces en la base piloto</small></div>
 <div class="group-response-list">${byGroup.map(({g,rows})=>`<div class="group-response"><div class="response-group" ${groupTone(g.id)}><span class="response-dot"></span>${H(g.name)}</div><div class="response-rows">${rows.map(({p,r})=>`<button class="response-row" data-action="relation" data-drug="${H(a.id)}" data-micro="${H(p.id)}">${glyph(r.status)}<span>${H(p.name)}</span><small>${H(statusMap[statusKey(r.status)].short)}</small>${I('arrow-up-right')}</button>`).join('')}</div></div>`).join('')||emptyResult('No existen cruces documentados todavía. No se asume falta de actividad.')}</div></section>
 <section class="subsection"><div class="subsection-head"><span>03</span><h3>Aplicación y límites</h3></div><div class="notes-split"><div class="notes-positive"><span class="notes-label">${I('clipboard-list')} PENSAR EN</span><p>${H(a.context||a.pearl||'Depende de indicación, susceptibilidad y contexto.')}</p></div><div class="notes-caution"><span class="notes-label">${I('shield-alert')} OJO CON</span><p>${H(a.limitations||'Verificar resistencia, foco, toxicidad y pruebas de susceptibilidad.')}</p></div></div></section>
 <section class="detail-actions">${btn('Comparar este antibiótico','compare-add:'+a.id,'ink','arrow-left-right')}${btn('Abrir mapa Micro × ATB','nav:cruce','outline','grid-3x3')}</section>
 <p class="editorial-warning">Información editorial en desarrollo. No usar estas relaciones como validación de prescripción.</p>`;}
function renderDrugs(){return `${pageHeader('02 / FARMACOLOGÍA ANTIBACTERIANA','Antibióticos, <i>sin atajos.</i>','Toda la biblioteca: familias, subgrupos, mecanismo, aplicaciones, limitaciones y espectro disponible.')}${crossModeStrip()}<div class="library-frame"><div class="library-intro">${catalogHeader('ÍNDICE FARMACOLÓGICO','111 agentes · 26 familias','Selecciona primero una familia y después un antibiótico.','pill')}<span class="library-status">EXPLORACIÓN INDEPENDIENTE</span></div><div class="library-columns drug-library">${drugList()}${drugCards()}<article class="detail-panel">${drugDetail()}</article></div></div>`;}
function microGroupsList(){return `<div class="catalog-filter"><div class="catalog-search">${I('search')}<input id="microSearch" placeholder="Bacteria, fenotipo, síndrome…" value="${H(state.query)}"/></div><div class="catalog-label">TAXONOMÍA CLÍNICA <span>${D.groups.length}</span></div><div class="catalog-groups"><button class="family-filter ${state.group==='all'?'active':''}" data-action="group:all">Todos los grupos <small>${D.pathogens.length}</small></button>${D.groups.map(g=>`<button class="family-filter colored ${state.group===g.id?'active':''}" ${groupTone(g.id)} data-action="group:${g.id}"><i></i>${H(g.name)}<small>${microIn(g.id).length}</small></button>`).join('')}</div></div>`;}
function microCards(){const list=D.pathogens.filter(p=>(state.group==='all'||p.groupId===state.group)&&N([p.name,p.morphology,p.identity,...(p.aliases||[])].join(' ')).includes(activeQuery()));let groups=D.groups.map(g=>({g,entries:list.filter(p=>p.groupId===g.id)})).filter(x=>x.entries.length);return `<div class="catalog-stream">${groups.map(({g,entries})=>`<div class="catalog-family-title colored" ${groupTone(g.id)}><span class="dot"></span><span>${H(g.name)}</span><i>${entries.length}</i></div>${entries.map(p=>`<button class="catalog-row ${state.activeMicro===p.id?'selected':''}" data-action="micro-select:${H(p.id)}"><span class="micro-mark" ${groupTone(p.groupId)}>${I('microscope')}</span><span class="catalog-row-copy"><b>${H(p.name)}</b><small>${H(p.morphology)}</small></span><span class="row-trailing">${relByMicro(p.id).length||'—'} ${I('chevron-right')}</span></button>`).join('')}`).join('')||emptyResult('No se encontraron microorganismos.')}</div>`;}
function microIdentityPath(p){let g=G(p.groupId),domain=p.domain||'Microorganismo';return `<div class="identity-path"><div><span class="path-icon">${I('dna')}</span><small>ESTRUCTURA</small><b>${H(domain)}</b></div><span class="path-connector">${I('arrow-right')}</span><div ${groupTone(p.groupId)}><span class="path-icon toned">${I('layers-3')}</span><small>FAMILIA / GRUPO</small><b>${H(g?.name||'Grupo')}</b></div><span class="path-connector">${I('arrow-right')}</span><div><span class="path-icon">${I('scan')}</span><small>IDENTIFICACIÓN</small><b>${H(p.morphology||'Morfología variable')}</b></div></div>`;}
function relatedDisease(p){let associated=D.syndromes.filter(s=>(s.pathogenIds||[]).includes(p.id) || (p.syndromeIds||[]).includes(s.id));return associated;}
function phenotypeSpotlight(p){const byId={'e-coli-blee':'blee','escherichia-coli-cre':'cre','klebsiella-pneumoniae-cre':'cre','pseudomonas-aeruginosa-dtr':'dtr','acinetobacter-baumannii-crab':'crab','stenotrophomonas-maltophilia':'steno','enterobacter-cloacae':'ampc','citrobacter-freundii':'ampc'};let topic=X.topics?.find(x=>x.id===byId[p.id]);return topic?`<div class="phenotype-spotlight"><div><small>CAPA IDSA 2026 · ${H(topic.tag)}</small><h3>${H(topic.name)}</h3><p>${H(topic.explain)}</p><strong>${H(topic.why)}</strong></div><a href="${H(topic.link)}" target="_blank" rel="noopener noreferrer">Fuente IDSA ${I('arrow-up-right')}</a></div>`:'';}
function microDetail(){let p=P(state.activeMicro)||D.pathogens[0],g=G(p.groupId),related=relByMicro(p.id),diseases=relatedDisease(p),media=X.media?.[p.id];return `<div class="detail-head micro-headline" ${groupTone(p.groupId)}><div class="head-number">MICRO / ${String(D.pathogens.indexOf(p)+1).padStart(3,'0')} ${groupPill(p.groupId,true)}</div><h2>${H(p.name)}</h2><div class="detail-subhead"><span class="detail-tag micro-tint">${H(p.domain)}</span><span class="detail-tag micro-tint">${H(p.morphology)}</span></div><p>${H(p.identity||'Identificación taxonómica en desarrollo.')}</p></div>
 <div class="identity-illustration"><div class="figure-label">FICHA DE IDENTIDAD / ESQUEMA DE LECTURA</div>${microIdentityPath(p)}</div>
 ${media?`<div class="micro-media"><img src="${H(media.src)}" loading="lazy" alt="Microfotografía de ${H(p.name)}"/><div><small class="mono-overline">ATLAS MICROSCÓPICO</small><b>${H(media.caption)}</b><a href="${H(media.creditUrl)}" target="_blank" rel="noopener noreferrer">Fuente: ${H(media.credit)} ↗</a><p>Imagen ilustrativa del microorganismo; no identifica fenotipo resistente ni reemplaza cultivo.</p></div></div>`:''}
 ${phenotypeSpotlight(p)}
 <section class="subsection"><div class="subsection-head"><span>01</span><h3>¿Cuándo pensar en él?</h3></div><div class="micro-logic"><div class="micro-logic-cell"><small>CLAVE DE IDENTIDAD</small><p>${H(p.identity)}</p></div><div class="micro-logic-cell"><small>PISTA CLÍNICA</small><p>${H(p.clinical||'Relacionar con el sitio de infección, presentación y epidemiología.')}</p></div><div class="micro-logic-cell"><small>ERROR FRECUENTE</small><p>${H(p.pearl||'Evitar asumir susceptibilidad solo por el nombre de la especie.')}</p></div></div></section>
 <section class="subsection"><div class="subsection-head"><span>02</span><h3>Enfermedades y escenarios asociados</h3></div><div class="syndrome-pills">${diseases.length?diseases.map(s=>`<button data-action="syndrome-select:${H(s.id)}">${I('arrow-up-right')} ${H(s.name)}</button>`).join(''):emptyResult('Sin síndromes enlazados aún. La descripción clínica sigue disponible arriba.')}</div></section>
 <section class="subsection"><div class="subsection-head"><span>03</span><h3>Antibióticos con relación registrada</h3><small>${related.length} de ${D.antibiotics.length}</small></div><div class="relation-stack">${related.length?related.sort((x,y)=>(['active','conditional','none'].indexOf(x.status)-['active','conditional','none'].indexOf(y.status))).map(r=>`<button class="relation-list-row" data-action="relation" data-drug="${H(r.antibiotic)}" data-micro="${H(p.id)}">${glyph(r.status)}<b>${H(A(r.antibiotic)?.name||r.antibiotic)}</b><span>${H(statusMap[statusKey(r.status)].label)}</span>${I('arrow-up-right')}</button>`).join(''):emptyResult('Todavía no hay relaciones validadas en esta base; esto no implica resistencia.')}</div></section>
 <div class="detail-actions">${btn('Cruzar con antibióticos','nav:cruce','ink','grid-3x3')}${btn('Guías y resistencia','nav:fuentes','outline','book-open')}</div><p class="editorial-warning">Un fenotipo de resistencia necesita comprobación microbiológica. La morfología no predice susceptibilidad.</p>`;}
function renderMicro(){return `${pageHeader('03 / MICROBIOLOGÍA CLÍNICA','Conoce al <i>microorganismo.</i>','Desde su identidad y morfología hasta las enfermedades en las que conviene considerarlo.')}${crossModeStrip()}<div class="library-frame"><div class="library-intro">${catalogHeader('ÍNDICE TAXONÓMICO','79 especies y fenotipos','Los colores distinguen grupos, no indican resistencia.','microscope')}<span class="library-status">EXPLORACIÓN INDEPENDIENTE</span></div><div class="library-columns micro-library">${microGroupsList()}${microCards()}<article class="detail-panel">${microDetail()}</article></div></div>`;}
function syndromeContent(){let s=S(state.activeSyndrome)||D.syndromes[0];let pats=(s.pathogenIds||[]).map(P).filter(Boolean);let possible=[...new Set(pats.flatMap(p=>relByMicro(p.id).filter(r=>r.status==='active'||r.status==='conditional').map(r=>r.antibiotic)))].map(A).filter(Boolean).slice(0,20);let guide=(s.referenceKeys||[]).map(k=>D.guides[k]).filter(Boolean);return `<article class="clinical-detail"><div class="clinical-focus"><div class="clinical-topline">PUNTO DE PARTIDA <span>${H(s.site||'Clínica')}</span></div><h2>${H(s.name)}</h2><p>${H(s.summary||'Razonar por síndrome, gravedad y contexto.')}</p></div>
 <div class="thinking-trail"><div><span class="trail-index">01</span><b>Reconocer síndrome</b><small>Foco y gravedad</small></div><span class="trail-arrow">→</span><div><span class="trail-index">02</span><b>Considerar patógenos</b><small>Clínica + epidemiología</small></div><span class="trail-arrow">→</span><div><span class="trail-index">03</span><b>Evaluar cobertura</b><small>AST + PK/PD + guías</small></div></div>
 <div class="clinical-sections"><div class="clinical-box"><h3>${I('clipboard-check')} Claves a evaluar</h3><ul>${(s.clues||[]).map(c=>`<li>${H(c)}</li>`).join('')}</ul></div><div class="clinical-box"><h3>${I('microscope')} Microorganismos relacionados</h3><div class="clinical-patogens">${pats.map(p=>`<button data-action="micro:${H(p.id)}" ${groupTone(p.groupId)}><i></i><span>${H(p.name)}</span>${I('arrow-up-right')}</button>`).join('')||'<p>Sin patógenos enlazados.</p>'}</div></div></div>
 <div class="clinical-downstream"><div class="section-divider"><span>LECTURA INVERSA · ANTIMICROBIANOS</span></div><p><b>${possible.length} agentes</b> presentan alguna relación positiva o condicionada con los patógenos anteriores. <strong>Esta lista no es un esquema empírico ni una selección por preferencia.</strong></p><div class="clinical-drugs">${possible.map(a=>`<button data-action="drug:${H(a.id)}">${I('pill')}${H(a.name)} ${I('arrow-up-right')}</button>`).join('')}</div></div>
 <div class="guides-foot"><b>Referencias vinculadas</b>${guide.map(g=>`<a href="${H(g.url)}" target="_blank" rel="noopener noreferrer">${H(g.title)} ↗</a>`).join('')||'<span>Consultar fuentes generales y guías locales.</span>'}</div></article>`;}
function renderClinica(){return `${pageHeader('04 / RAZONAMIENTO CLÍNICO','Del síndrome al <i>patógeno.</i>','El contexto clínico determina qué buscar antes de interpretar el espectro.')}
 <div class="clinical-layout"><div class="clinical-index"><div class="mono-overline">22 SÍNDROMES</div><h3>Elige una infección</h3><div class="clinical-links">${D.syndromes.map(s=>`<button class="${state.activeSyndrome===s.id?'active':''}" data-action="syndrome-select:${H(s.id)}"><small>${H(s.site)}</small><b>${H(s.name)}</b>${I('chevron-right')}</button>`).join('')}</div></div>${syndromeContent()}</div>`;}
function compareToolbar(){return `<div class="compare-picker"><div class="compare-lab"><b>Selecciona antibióticos</b><small>Hasta 4 fármacos; las columnas se sincronizan por grupo</small></div><div class="compare-choices">${state.compare.map(id=>`<span class="chosen-drug">${H(A(id)?.name||id)}<button data-action="compare-remove:${H(id)}" aria-label="Quitar">×</button></span>`).join('')}<select id="compareAdd"><option value="">+ Añadir antibiótico</option>${D.antibiotics.filter(a=>!state.compare.includes(a.id)).map(a=>`<option value="${H(a.id)}">${H(a.name)}</option>`).join('')}</select></div></div>`;}
function renderCompare(){let groups=D.groups;return `${pageHeader('05 / COMPARAR','Enfrenta dos ideas. <i>No supongas.</i>','Compara cuatro antibióticos a la vez, con la misma escala microbiológica y sus puntos no evaluados.')}${compareToolbar()}<div class="compare-grid">${state.compare.map(id=>{const a=A(id),r=relByDrug(id);return `<article class="compare-column"><div class="compare-head"><div class="compare-icon">${I('pill')}</div><small>${H(a?.family||'Antibiótico')}</small><h2>${H(a?.name||id)}</h2><p>${H(a?.subgroup||'')}</p></div><div class="compare-facts"><small>MECANISMO DE ACCIÓN</small><p>${H(a?.mechanism||'Sin dato')}</p><small>CONTEXTO</small><p>${H(minWords(a?.context||a?.pearl,25))}</p></div><div class="compare-spectrum">${groups.map(g=>{const sum=summaryStatus(id,g.id);return `<button class="compare-group" ${groupTone(g.id)} data-action="group-inspect" data-drug="${H(id)}" data-group="${H(g.id)}"><span class="compare-group-name"><i></i>${H(g.name)}</span><span class="mini-bar"><em style="width:${sum.total?sum.known/sum.total*100:0}%;background:var(--tone)"></em></span><small>${sum.known}/${sum.total}</small></button>`;}).join('')}</div><p class="compare-foot">${r.length} relaciones registradas. La barra representa volumen de datos, no porcentaje de susceptibilidad.</p></article>`;}).join('')||emptyResult('Selecciona al menos un antibiótico.')}</div>`;}
function renderAprender(){const lesson=D.lessons.find(x=>x.id===state.learnId)||D.lessons[0];return `${pageHeader('06 / APRENDER','Primero entiende. <i>Después compara.</i>','Una secuencia de lectura: Gram, morfología, mecanismos, resistencia y decisiones clínicas.')}
 <div class="learn-layout"><aside class="learn-menu"><div class="mono-overline">LABORATORIO DE CONCEPTOS</div>${D.lessons.map((l,i)=>`<button class="${lesson.id===l.id?'active':''}" data-action="lesson:${H(l.id)}"><span>${String(i+1).padStart(2,'0')}</span><b>${H(l.title)}</b>${I('chevron-right')}</button>`).join('')}</aside><article class="learn-article"><div class="lesson-eyebrow">${H(lesson.category)} · APRENDIZAJE DIRIGIDO</div><h2>${H(lesson.title)}</h2><p class="lesson-lead">${H(lesson.body)}</p><div class="learn-diagram"><div class="diagram-node"><span>${I('scan')}</span><b>Observar</b><small>Identidad y pista inicial</small></div><span class="diagram-link">→</span><div class="diagram-node"><span>${I('git-branch')}</span><b>Interpretar</b><small>Mecanismo y resistencia</small></div><span class="diagram-link">→</span><div class="diagram-node"><span>${I('clipboard-check')}</span><b>Contextualizar</b><small>Síndrome + evidencia</small></div></div><div class="lesson-explanation"><span class="mono-overline">¿POR QUÉ ES IMPORTANTE?</span><p>${H(lesson.why)}</p></div><div class="lesson-notes"><span>${I('book-open-text')} Referencias del tema</span>${(lesson.refs||[]).map(k=>`<small>${H(k)}</small>`).join('')}</div></article></div>
 <section class="insights-section"><div class="section-kicker"><span class="section-accent"></span> RESISTENCIA · ACTUALIZACIÓN IDSA 2026</div><h2>Fenotipos que cambian la conversación</h2><div class="insights-grid">${(X.topics||[]).map(t=>`<article class="insight-card"><small>${H(t.tag)}</small><h3>${H(t.name)}</h3><b>${H(t.hint)}</b><p>${H(t.explain)}</p><a href="${H(t.link)}" target="_blank" rel="noopener noreferrer">Leer documento IDSA ${I('arrow-up-right')}</a></article>`).join('')}</div></section>`;}
function renderFuentes(){const refs=Object.entries(D.guides);let c={};refs.forEach(([key,g])=>{(c[g.category]??=[]).push({key,...g})});return `${pageHeader('07 / FUENTES Y EDICIÓN','Evidencia con <i>trazabilidad.</i>','Las lecturas originales no sustituyen textos completos, guías ni evaluación del contexto local.')}
 <div class="source-summary"><div><span>${D.guides&&Object.keys(D.guides).length}</span><small>GUÍAS Y FUENTES ENLAZADAS</small></div><div><span>${D.relations.length}</span><small>RELACIONES EN BASE PILOTO</small></div><div><span>${D.antibiotics.length}</span><small>AGENTES CATALOGADOS</small></div></div>
 <div class="sources-layout"><section><div class="section-kicker"><span class="section-accent"></span> REFERENCIAS EN LÍNEA</div>${Object.entries(c).map(([category,list])=>`<div class="source-group"><h3>${H(category)}</h3>${list.map(g=>`<a href="${H(g.url)}" target="_blank" rel="noopener noreferrer" class="source-entry"><span class="source-icon">${I('file-text')}</span><span><b>${H(g.title)}</b><small>${H(g.topic||'')} · ${H(g.takeaway||'')}</small></span>${I('arrow-up-right')}</a>`).join('')}</div>`).join('')}</section><aside class="sources-aside"><div class="aside-panel"><span class="mono-overline">NOTA EDITORIAL</span><h3>¿Por qué hay celdas vacías?</h3><p>Porque el catálogo es más amplio que las relaciones clínicamente documentadas. <strong>Vacío no quiere decir resistente.</strong> La información debe ser revisada por combinación especie–fármaco y contexto de infección.</p><div class="aside-mini-count">${D.relations.length} cruces registrados <span>vs.</span> ${D.antibiotics.length*D.pathogens.length} potenciales</div></div><div class="aside-panel neutral"><span class="mono-overline">BIBLIOGRAFÍA DE BASE</span>${(D.meta.bibliography||[]).map(a=>`<div class="bibliog"><b>${H(a.title)}</b><small>${H(a.category)}</small></div>`).join('')}</div></aside></div>`;}
function renderDrawer(){let o=state.drawer;if(!o)return '';let content='';if(o.type==='relation'){
 const a=A(o.drug),p=P(o.micro),r=R(o.drug,o.micro);const status=statusKey(r?.status);content=`<div class="drawer-eyebrow">RELACIÓN MICROBIOLÓGICA</div><h2>${H(a?.name)} <span class="drawer-cross">×</span> ${H(p?.name)}</h2>${groupPill(p?.groupId)}<div class="drawer-state">${statusLabel(status)}</div><div class="drawer-note"><span class="mono-overline">INTERPRETACIÓN</span><p>${H(r?.note||'Esta combinación todavía no ha sido evaluada de forma individual en la base editorial. No se debe inferir actividad ni resistencia.')}</p></div><div class="drawer-note pale"><span class="mono-overline">IMPORTANTE</span><p>El espectro teórico no equivale a selección terapéutica. El aislamiento, antibiograma, foco, susceptibilidad local y farmacocinética importan.</p></div><div class="drawer-jumps">${btn('Ver antibiótico','drug:'+o.drug,'ink','pill')}${btn('Ver microorganismo','micro:'+o.micro,'outline','microscope')}</div>${r?.referenceKeys?.length?`<div class="drawer-sources"><span class="mono-overline">FUENTES VINCULADAS</span>${r.referenceKeys.map(sourceLink).join('')}</div>`:''}`;
 } else if(o.type==='group'){
 let a=A(o.drug),g=G(o.group),species=microIn(o.group);content=`<div class="drawer-eyebrow">TERRITORIO MICROBIOLÓGICO</div><h2>${H(g?.name)}</h2><div class="drawer-territory" ${groupTone(o.group)}><div class="drawer-color-bar"></div><p>Explorando <b>${H(a?.name)}</b> frente a ${species.length} microorganismos de este territorio.</p></div><div class="territory-species">${species.map(p=>{let r=R(o.drug,p.id),status=statusKey(r?.status);return `<button data-action="relation" data-drug="${H(o.drug)}" data-micro="${H(p.id)}">${glyph(status)}<b>${H(p.name)}</b><small>${H(statusMap[status].short)}</small>${I('chevron-right')}</button>`;}).join('')}</div><div class="drawer-note pale"><span class="mono-overline">LEE CON CUIDADO</span><p>Las bandas separan especies para evitar que un resultado parcial se interprete como cobertura universal del grupo.</p></div>`;
 }return `<div class="overlay drawer-overlay" data-action="drawer-close"><aside class="drawer" role="dialog" aria-modal="true" aria-label="Inspector de cobertura"><div class="drawer-header"><b>INSPECTOR CLÍNICO <span>ATLAS / 05</span></b>${iconButton('x','drawer-close','Cerrar')}</div><div class="drawer-body">${content}</div></aside></div>`;}
function renderPalette(){return `<div class="overlay palette-overlay" data-action="palette-close"><aside class="palette-sheet" role="dialog" aria-modal="true" aria-label="Personalizar colores"><div class="palette-head"><div><div class="mono-overline">SISTEMA CROMÁTICO / PERSONALIZABLE</div><h2>Tu atlas, tus colores.</h2><p>Cada grupo conserva su color en mapas, fichas y etiquetas. La actividad se marca con símbolos, no con los colores.</p></div>${iconButton('x','palette-close','Cerrar')}</div><div class="palette-presets"><button data-action="preset:spectrum">Spectrum · vivo</button><button data-action="preset:studio">Estudio · cálido</button><button data-action="preset:night">Contraste · intenso</button></div><div class="palette-list">${D.groups.map(g=>`<label class="palette-color-row" ${groupTone(g.id)}><span class="palette-swatch" style="background:${H(colors[g.id])}"></span><b>${H(g.name)}</b><span class="palette-hex" id="hex-${H(g.id)}">${H(colors[g.id])}</span><input type="color" data-color="${H(g.id)}" value="${H(colors[g.id])}" aria-label="Color de ${H(g.name)}"></label>`).join('')}</div><div class="palette-actions">${btn('Restablecer','preset:spectrum','ghost','rotate-ccw')}${btn('Copiar paleta JSON','palette-export','ink','copy')}</div><div class="palette-note">La personalización se guarda automáticamente en este navegador; la puedes exportar.</div></aside></div>`;}
function renderSearch(){let q=N(state.searchQuery);let items=[...D.antibiotics.map(a=>({type:'drug',id:a.id,name:a.name,tag:a.family})),...D.pathogens.map(p=>({type:'micro',id:p.id,name:p.name,tag:G(p.groupId)?.name||''})),...D.syndromes.map(s=>({type:'syndrome',id:s.id,name:s.name,tag:s.site}))];let matches=items.filter(x=>N(x.name+' '+x.tag).includes(q)).slice(0,28);return `<div class="overlay search-overlay" data-action="search-close"><div class="command-modal" role="dialog" aria-modal="true" aria-label="Búsqueda global"><div class="command-input-row">${I('search')}<input id="commandInput" autofocus placeholder="Busca E. coli, BLEE, ceftriaxona, meningitis…" value="${H(state.searchQuery)}">${iconButton('x','search-close','Cerrar')}</div><div class="command-results">${matches.map(x=>`<button data-action="${x.type}:${H(x.id)}"><span class="command-type ${x.type}">${I(x.type==='drug'?'pill':x.type==='micro'?'microscope':'git-branch')}</span><span><b>${H(x.name)}</b><small>${H(x.tag)}</small></span>${I('arrow-up-right')}</button>`).join('')||emptyResult('Sin resultados para esta búsqueda.')}</div><div class="command-foot"><span>Buscar por nombre, grupo, familia o síndrome</span><kbd>ESC para cerrar</kbd></div></div></div>`;}
function mainView(){switch(state.view){case'antibioticos':return renderDrugs();case'microorganismos':return renderMicro();case'clinica':return renderClinica();case'comparar':return renderCompare();case'aprender':return renderAprender();case'fuentes':return renderFuentes();default:return renderCross();}}
function render(opts={}){if(!D.antibiotics)return;const hasModal=state.searchOpen;shell(mainView()); if(hasModal){let i=document.getElementById('commandInput');if(i){i.focus();i.setSelectionRange(i.value.length,i.value.length);}}}
function routeView(){let raw=(location.hash||'#/cruce').replace(/^#\//,'').split('/')[0];state.view=['cruce','antibioticos','microorganismos','clinica','comparar','aprender','fuentes'].includes(raw)?raw:'cruce';state.drawer=null;state.searchOpen=false;state.paletteOpen=false;state.query='';state.group='all';state.family='all';render();}
function navigate(view){state.drawer=null;state.searchOpen=false;state.paletteOpen=false; if(location.hash!==nav(view))location.hash=nav(view);else {state.view=view;render();}document.querySelector('.shell-main')?.scrollTo(0,0);window.scrollTo(0,0);}
function runAction(action,el){if(!action)return;let [what,...rest]=action.split(':'),payload=rest.join(':');switch(what){
 case'nav':navigate(payload);return;
 case'map':state.mapView=payload;break;
 case'group':state.group=payload;break;
 case'family':state.family=payload;break;
 case'drug-select':state.activeDrug=payload;break;
 case'micro-select':state.activeMicro=payload;break;
 case'drug':state.activeDrug=payload;navigate('antibioticos');return;
 case'micro':state.activeMicro=payload;navigate('microorganismos');return;
 case'syndrome':case'syndrome-select':state.activeSyndrome=payload;navigate('clinica');return;
 case'lesson':state.learnId=payload;break;
 case'relation':state.drawer={type:'relation',drug:el.dataset.drug,micro:el.dataset.micro};break;
 case'group-inspect':state.drawer={type:'group',drug:el.dataset.drug,group:el.dataset.group};break;
 case'drawer-close':state.drawer=null;break;
 case'palette':state.paletteOpen=true;break;
 case'palette-close':state.paletteOpen=false;break;
 case'search-open':state.searchOpen=true;state.searchQuery='';break;
 case'search-close':state.searchOpen=false;break;
 case'filter-toggle':state.filtersOpen=!state.filtersOpen;break;
 case'legend':state.focused=state.focused==='legend'?null:'legend';break;
 case'reset-filter':state.query='';state.group='all';state.family='all';state.onlyKnown=true;break;
 case'compare-add':if(!state.compare.includes(payload)&&state.compare.length<4)state.compare.push(payload);navigate('comparar');return;
 case'compare-remove':state.compare=state.compare.filter(x=>x!==payload);break;
 case'palette-export':{const txt=JSON.stringify({version:'5.0',groups:colors},null,2);navigator.clipboard?.writeText(txt).then(()=>showToast('Paleta copiada')).catch(()=>showToast('No se pudo copiar'));return;}
 case'preset':{const palette=payload==='studio'?['#c64b42','#cf673d','#805c94','#9b528d','#cb8d30','#3f927f','#4a91a8','#a28645','#758c47','#596cbd','#a65f87','#5674a3']:payload==='night'?['#fc576b','#ff9652','#ac6aff','#d766b0','#ffbd36','#00bcac','#5ebad5','#e0b348','#8fbb5c','#9d9cff','#ed70bf','#7c9dff']:defaults;D.groups.forEach((g,i)=>colors[g.id]=palette[i%palette.length]);saveColors();break;}
 case'share':{navigator.clipboard?.writeText(location.href).then(()=>showToast('Enlace copiado')).catch(()=>showToast('No se pudo copiar'));return;}
 default:return;
}render();}
let toastTimer;function showToast(t){document.querySelector('.toast')?.remove();let e=document.createElement('div');e.className='toast';e.textContent=t;document.body.appendChild(e);clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.remove(),2600);}
function saveColors(){try{localStorage.setItem('atb_atlas_palette_v5',JSON.stringify(colors));}catch(err){console.warn('Local color settings unavailable',err);}applyPalette();}
ROOT.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target)return;let overlay=target.classList.contains('overlay');if(overlay&&e.target!==target)return;const action=target.dataset.action;if(action==='group-inspect'||action==='relation')runAction(action,target);else runAction(action,target);});
ROOT.addEventListener('change',e=>{const t=e.target;switch(t.id){case'familySelect':state.family=t.value;render();break;case'knownToggle':state.onlyKnown=t.checked;render();break;case'densitySelect':state.density=t.value;render();break;case'compareAdd':if(t.value&&!state.compare.includes(t.value)&&state.compare.length<4)state.compare.push(t.value);render();break;default:if(t.matches('input[type=color][data-color]')){colors[t.dataset.color]=t.value;saveColors();document.getElementById('hex-'+t.dataset.color).textContent=t.value;document.querySelector(`.palette-color-row:has([data-color="${t.dataset.color}"]) .palette-swatch`).style.background=t.value;}}});
let inputTimer;ROOT.addEventListener('input',e=>{const t=e.target;if(t.matches('input[type=color][data-color]')){colors[t.dataset.color]=t.value;saveColors();const row=t.closest('.palette-color-row');row.querySelector('.palette-hex').textContent=t.value;row.querySelector('.palette-swatch').style.background=t.value;return;}
 if(t.id==='commandInput'){state.searchQuery=t.value;const position=t.selectionStart;render();const n=document.getElementById('commandInput');n?.focus();n?.setSelectionRange(position,position);return;}
 if(['crossSearch','drugSearch','microSearch'].includes(t.id)){state.query=t.value;const id=t.id,pos=t.selectionStart;clearTimeout(inputTimer);inputTimer=setTimeout(()=>{render();let newInput=document.getElementById(id);newInput?.focus();try{newInput?.setSelectionRange(pos,pos);}catch{}},140);}
});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();state.searchOpen=true;state.searchQuery='';render();} if(e.key==='Escape'&&(state.drawer||state.paletteOpen||state.searchOpen)){state.drawer=null;state.paletteOpen=false;state.searchOpen=false;render();}});
window.addEventListener('hashchange',routeView);
async function boot(){try{let [data,extra]=await Promise.all([fetch('./data/atlas.json',{cache:'no-store'}),fetch('./data/insights.json',{cache:'no-store'})]);if(!data.ok||!extra.ok)throw Error(`No se pudo cargar el catálogo (${data.status}/${extra.status})`);D=await data.json();X=await extra.json();colors=initialPalette();applyPalette();routeView();}catch(err){ROOT.innerHTML=`<div class="load-error"><b>ATB Atlas no pudo abrir su catálogo</b><p>${H(err.message)}</p><small>Para revisar archivos locales se requiere un servidor HTTP; GitHub Pages carga automáticamente.</small></div>`;console.error(err);}}
boot();